mapper.select:
SELECT id, code, description, sort_order, course_id, created_at, updated_at
FROM edu.group_learning_outcomes
WHERE id = #{id}

SELECT COALESCE(MAX(sort_order), 0)
FROM edu.group_learning_outcomes
WHERE course_id = #{courseId}

mapper.update:
UPDATE edu.group_learning_outcomes
SET code = #{code},
    sort_order = #{sortOrder},
    updated_at = NOW()
WHERE id = #{id}
  AND course_id = #{courseId}

mapper.delete:
DELETE FROM edu.group_learning_outcomes
WHERE id = #{id}
  AND course_id = #{courseId}
